# Atores do diagrama de casos de uso (Elicitação de Requisitos). Ficam como
# Groups sem permissões: cada componente associa as permissões das suas
# operações quando elas existirem. Podem ser editados pelo Django Admin.
PAPEIS = ["Técnico", "Configurador", "CAM/SECOGE", "Avaliado"]


def criar_papeis(apps, schema_editor):
    Group = apps.get_model("auth", "Group")
    for nome in PAPEIS:
        Group.objects.get_or_create(name=nome)


def remover_papeis(apps, schema_editor):
    Group = apps.get_model("auth", "Group")
    Group.objects.filter(name__in=PAPEIS).delete()


